 const [reportProfiles,setReportProfiles]=useState([]),[openReportStudent,setOpenReportStudent]=useState(''),[reportProfileDraft,setReportProfileDraft]=useState({}),[reportPhotoBusy,setReportPhotoBusy]=useState(false),[reportMarksDraft,setReportMarksDraft]=useState({});
 const [branding,setBranding]=useState({schoolName:'',address:'',medium:'',contact:'',logoData:'',buildingData:'',bg:'#ffffff',heading:'#087a3b',table:'#087a3b',text:'#173b2c',border:'#168044',font:'Arial',fontSize:'12'});
 const schoolStudents=useMemo(()=>students.filter(s=>!schoolId||s.schoolId===schoolId),[students,schoolId]);
