 const activeExam=exams.find(e=>e.id===selectedExam);
 const load=async()=>{if(!schoolId){setLoading(false);return;}setLoading(true);setError('');try{const [e,m,sc]=await Promise.all([getDocs(query(collection(db,'schoolExams'),where('schoolId','==',schoolId))),getDocs(query(collection(db,'examMarks'),where('schoolId','==',schoolId))),getDocs(query(collection(db,'schoolSubjects'),where('schoolId','==',schoolId)))]);setExams(e.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>(a.createdAt?.seconds||0)-(b.createdAt?.seconds||0)));setMarks(m.docs.map(d=>({id:d.id,...d.data()})));const subjectDocs=sc.docs.map(d=>({id:d.id,...d.data()}));setSubjectConfigs(subjectDocs.filter(x=>x.configType==='class-subject-list'));setReportProfiles(subjectDocs.filter(x=>x.configType==='student-report-profile'));const b=subjectDocs.find(x=>x.configType==='school-report-branding');if(b)setBranding(v=>({...v,...b}));}catch(x){setError(errText(x));}finally{setLoading(false);}};
