 const saveExam=async()=>{if(!schoolId||!examForm.name.trim())return setError('School and Exam Name are required.');setBusy(true);setError('');setNotice('');try{const payload={...examForm,schoolId,schoolName:schoolName||'',updatedAt:serverTimestamp(),updatedBy:profile?.uid||profile?.email||''};if(editingExam){await updateDoc(doc(db,'schoolExams',editingExam),payload);setNotice('Exam updated successfully.');}else{const r=await addDoc(collection(db,'schoolExams'),{...payload,createdAt:serverTimestamp(),createdBy:profile?.uid||profile?.email||''});setSelectedExam(r.id);setNotice('Exam created successfully.');}setEditingExam(null);await load();}catch(x){setError(errText(x));}finally{setBusy(false);}};
 const startEdit=e=>{setEditingExam(e.id);setExamForm({name:e.name||'',pattern:e.pattern||'Custom',session:e.session||'2026-27',startDate:e.startDate||'',endDate:e.endDate||'',status:e.status||'Draft'});setTab('Exams');};
 const saveMarks=async()=>{if(!activeExam||!className||!subject)return setError('Select Exam, Class and Subject first.');setBusy(true);setError('');setNotice('');try{for(const s of classStudents){const v=entries[s.id]||{};const skill=skillEntries[s.id]||{};const existing=marks.find(m=>m.examId===selectedExam&&m.studentId===s.id&&m.subject===subject);const payload={schoolId,schoolName,examId:selectedExam,examName:activeExam.name,session:activeExam.session,className:s.className,section:s.section||'',studentId:s.id,studentName:s.name||'',admissionNo:s.admissionNo||'',fatherName:s.fatherName||'',subject,maximum:Number(v.maximum??activeExam.maximumMarks??100),obtained:v.absent?'':(v.obtained===''||v.obtained==null?'':Number(v.obtained)),absent:!!v.absent,remarks:v.remarks||'',skills:skill,updatedAt:serverTimestamp(),updatedBy:profile?.uid||profile?.email||''};if(existing)await updateDoc(doc(db,'examMarks',existing.id),payload);else await addDoc(collection(db,'examMarks'),{...payload,createdAt:serverTimestamp()});}setNotice('Marks saved for the selected class and subject.');await load();}catch(x){setError(errText(x));}finally{setBusy(false);}};
 useEffect(()=>{if(!selectedExam||!className||!subject)return;const next={},sk={};marks.filter(m=>m.examId===selectedExam&&m.className===className&&m.subject===subject).forEach(m=>{next[m.studentId]={maximum:m.maximum??100,obtained:m.obtained??'',absent:!!m.absent,remarks:m.remarks||''};sk[m.studentId]=m.skills||{};});setEntries(next);setSkillEntries(sk);},[selectedExam,className,subject,marks]);
 const studentResults=useMemo(()=>{const grouped={};marks.filter(m=>m.examId===selectedExam&&m.className===className&&(section==='All Sections'||m.section===section)).forEach(m=>{(grouped[m.studentId]??={studentId:m.studentId,name:m.studentName,admissionNo:m.admissionNo,fatherName:m.fatherName,section:m.section,subjects:[]}).subjects.push(m);});return Object.values(grouped).map(s=>{const valid=s.subjects.filter(x=>!x.absent&&x.obtained!==''&&x.obtained!=null);const total=valid.reduce((a,x)=>a+Number(x.obtained||0),0),max=valid.reduce((a,x)=>a+Number(x.maximum||0),0),pct=max?total/max*100:0;return {...s,total,max,pct,grade:pct>=90?'A+':pct>=80?'A':pct>=70?'B':pct>=60?'C':pct>=50?'D':pct>0?'E':'—',result:valid.length===0?'Pending':valid.length<s.subjects.length?'Incomplete':valid.every(x=>Number(x.obtained)>=Number(x.passing||0))?'Pass':'Check'};}).sort((a,b)=>b.pct-a.pct);},[marks,selectedExam,className,section]);
 const publish=async()=>{if(!activeExam)return;setBusy(true);try{await updateDoc(doc(db,'schoolExams',activeExam.id),{status:'Published',publishedAt:serverTimestamp(),publishedBy:profile?.uid||profile?.email||''});setNotice('Result published.');await load();}catch(x){setError(errText(x));}finally{setBusy(false);}};

